import React, { useState } from 'react';

export default function ScheduleVisitModal({ property, onClose }) {
  const [date, setDate] = useState('');
  const [time, setTime] = useState('');
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');

  if (!property) return null;

  const handleSubmit = (e) => {
    e.preventDefault();
    // Here you can add code to send data to the server
    alert(`✅ تم استلام طلبك لزيارة عقار "${property.type} في ${property.location.city}"\n\nالموعد: ${date} الساعة ${time}\nسنتواصل معك قريباً على الرقم: ${phone}`);
    onClose();
  };

  return (
    <div className="modal fade show d-block" tabIndex="-1" style={{ background: 'rgba(0,0,0,0.6)', zIndex: 1070 }}>
      <div className="modal-dialog modal-dialog-centered">
        <div className="modal-content shadow-lg border-0">
          <div className="modal-header bg-primary text-white">
            <h5 className="modal-title">📅 حجز موعد معاينة</h5>
            <button type="button" className="btn-close btn-close-white" onClick={onClose}></button>
          </div>
          <div className="modal-body">
            <div className="alert alert-light border mb-3 d-flex align-items-center">
                <img src={property.imageUrl} alt="" style={{width: 60, height: 60, objectFit: 'cover', borderRadius: 8}} className="me-3" />
                <div>
                    <strong>{property.type} - {property.price?.toLocaleString()} ج</strong>
                    <div className="small text-muted">{property.location.city}</div>
                </div>
            </div>
            <form onSubmit={handleSubmit}>
              <div className="row mb-3">
                <div className="col-6">
                  <label className="form-label small fw-bold">التاريخ المفضل</label>
                  <input type="date" className="form-control" required value={date} onChange={e => setDate(e.target.value)} />
                </div>
                <div className="col-6">
                  <label className="form-label small fw-bold">الوقت المناسب</label>
                  <input type="time" className="form-control" required value={time} onChange={e => setTime(e.target.value)} />
                </div>
              </div>
              <div className="mb-3">
                <label className="form-label small fw-bold">الاسم بالكامل</label>
                <input type="text" className="form-control" placeholder="اسمك" required value={name} onChange={e => setName(e.target.value)} />
              </div>
              <div className="mb-3">
                <label className="form-label small fw-bold">رقم الهاتف للتواصل</label>
                <input type="tel" className="form-control" placeholder="01xxxxxxxxx" required value={phone} onChange={e => setPhone(e.target.value)} />
              </div>
              <div className="d-grid">
                <button type="submit" className="btn btn-success fw-bold">تأكيد الحجز</button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}
